import com.nova.godzillagotchi.*;import java.io.*;import javax.imageio.*;import javax.imageio.stream.*;import javax.imageio.metadata.*;import java.awt.image.*;
public class RampagePreview {
 public static void main(String[] args)throws Exception{SkinPreview p=new SkinPreview(args[0]);SkinRenderer.State s=new SkinRenderer.State();s.pet=new Pet(0);s.city=new City();s.night=true;s.now=10000;
 ImageWriter writer=ImageIO.getImageWritersByFormatName("gif").next();try(ImageOutputStream out=ImageIO.createImageOutputStream(new File(args[1]+"-city-animation.gif"))){writer.setOutput(out);writer.prepareWriteSequence(null);boolean first=true;
 for(int move=0;move<4;move++){s.rampage=new Rampage(0);s.rampage.tick(0);s.rampage.tick(3200);s.rampage.vehicles[1]=new Rampage.Vehicle(1,1800);s.rampage.vehicles[2]=new Rampage.Vehicle(2,2500);s.rampage.hp=move==3?34:110;s.rampage.attack(move);
 for(int t=0;t<=Battle.DURATION_MS[move]+500;t+=80){s.rampage.tick(3200+t);BufferedImage frame=p.frame(s,480);ImageWriteParam param=writer.getDefaultWriteParam();IIOMetadata meta=writer.getDefaultImageMetadata(ImageTypeSpecifier.createFromRenderedImage(frame),param);String format=meta.getNativeMetadataFormatName();IIOMetadataNode root=(IIOMetadataNode)meta.getAsTree(format);IIOMetadataNode gce=FeedPreview.node(root,"GraphicControlExtension");gce.setAttribute("disposalMethod","none");gce.setAttribute("userInputFlag","FALSE");gce.setAttribute("transparentColorFlag","FALSE");gce.setAttribute("delayTime","8");gce.setAttribute("transparentColorIndex","0");if(first){IIOMetadataNode ext=FeedPreview.node(root,"ApplicationExtensions"),loop=new IIOMetadataNode("ApplicationExtension");loop.setAttribute("applicationID","NETSCAPE");loop.setAttribute("authenticationCode","2.0");loop.setUserObject(new byte[]{1,0,0});ext.appendChild(loop);first=false;}meta.setFromTree(format,root);writer.writeToSequence(new IIOImage(frame,null,meta),param);if(t>=Battle.HIT_MS[move]&&t<Battle.HIT_MS[move]+80)p.render(s,args[1]+"-city-"+Battle.MOVES[move].toLowerCase()+".png");}
 }
 writer.endWriteSequence();}writer.dispose();System.out.println("Rendered four city attacks, collapse and moving vehicles.");}
}
